package com.marceloaleixo.centrocirurgico.controller;

import com.marceloaleixo.centrocirurgico.entity.*;
import com.marceloaleixo.centrocirurgico.repository.*;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import java.time.LocalDate;

@Controller
@RequestMapping("/mutiroes")
public class MutiraoAgendaController {
 private final EventoMutiraoRepository eventos; private final DiaMutiraoRepository dias;
 private final EquipeDiaMutiraoRepository equipes; private final ColaboradorRepository colaboradores;
 private final SalaCirurgicaRepository salas; private final EscalaPlantaoRepository escalaPlantaoRepository;
 public MutiraoAgendaController(EventoMutiraoRepository eventos,DiaMutiraoRepository dias,EquipeDiaMutiraoRepository equipes,ColaboradorRepository colaboradores,SalaCirurgicaRepository salas,EscalaPlantaoRepository escalaPlantaoRepository){this.eventos=eventos;this.dias=dias;this.equipes=equipes;this.colaboradores=colaboradores;this.salas=salas;this.escalaPlantaoRepository=escalaPlantaoRepository;}
 @GetMapping public String listar(Model model){model.addAttribute("eventos",eventos.findAllByOrderByDataInicioDesc());return "mutiroes/lista";}
 @GetMapping("/novo") public String novo(Model model){EventoMutirao e=new EventoMutirao();e.setStatus("PLANEJADO");model.addAttribute("evento",e);model.addAttribute("edicao",false);return "mutiroes/formulario";}
 @GetMapping("/{id}/editar") public String editar(@PathVariable Long id,Model model,RedirectAttributes r){EventoMutirao e=eventos.findById(id).orElse(null);if(e==null){r.addFlashAttribute("erro","Mutirão não encontrado.");return "redirect:/mutiroes";}model.addAttribute("evento",e);model.addAttribute("edicao",true);return "mutiroes/formulario";}
 @PostMapping("/salvar") public String salvar(@ModelAttribute EventoMutirao e,RedirectAttributes r){
  if(e.getNome()==null||e.getNome().isBlank()||e.getNome().trim().length()>160||e.getEspecialidade()==null||e.getEspecialidade().isBlank()||e.getDataInicio()==null||e.getDataFim()==null||e.getDataFim().isBefore(e.getDataInicio())){r.addFlashAttribute("erro","Informe nome, especialidade e um período válido.");return e.getId()==null?"redirect:/mutiroes/novo":"redirect:/mutiroes/"+e.getId()+"/editar";}
  if(e.getStatus()==null||!java.util.Set.of("PLANEJADO","EM_PREPARACAO","EM_ANDAMENTO","CONCLUIDO","CANCELADO").contains(e.getStatus()))e.setStatus("PLANEJADO");
  e.setNome(e.getNome().trim());e.setEspecialidade(e.getEspecialidade().trim());if(e.getResponsavel()!=null)e.setResponsavel(e.getResponsavel().trim());eventos.save(e);r.addFlashAttribute("sucesso","Mutirão salvo com sucesso.");return "redirect:/mutiroes/"+e.getId()+"/dias";
 }
 @GetMapping("/{id}/dias") public String dias(@PathVariable Long id,Model model,RedirectAttributes r){EventoMutirao e=eventos.findById(id).orElse(null);if(e==null){r.addFlashAttribute("erro","Mutirão não encontrado.");return "redirect:/mutiroes";}model.addAttribute("evento",e);model.addAttribute("dias",dias.findByEventoIdOrderByDataAsc(id));model.addAttribute("salas",salas.findAll().stream().filter(SalaCirurgica::isAtiva).toList());model.addAttribute("colaboradores",colaboradores.findByAtivoTrueOrderByNomeAsc());model.addAttribute("salasEquipe",salas.findByAtivaTrueOrderByNomeAsc());model.addAttribute("novoDia",new DiaMutirao());return "mutiroes/dias";}
 @PostMapping("/{id}/dias/salvar") public String salvarDia(@PathVariable Long id,@RequestParam LocalDate data,@RequestParam(required=false) String descricao,@RequestParam(required=false) Long salaId,@RequestParam(required=false) String observacoes,RedirectAttributes r){EventoMutirao e=eventos.findById(id).orElse(null);if(e==null){r.addFlashAttribute("erro","Mutirão não encontrado.");return "redirect:/mutiroes";}if(data.isBefore(e.getDataInicio())||data.isAfter(e.getDataFim())){r.addFlashAttribute("erro","A data diária precisa estar dentro do período do evento.");return "redirect:/mutiroes/"+id+"/dias";}if(dias.existsByEventoIdAndData(id,data)){r.addFlashAttribute("erro","Já existe uma programação para essa data neste mutirão.");return "redirect:/mutiroes/"+id+"/dias";}DiaMutirao d=new DiaMutirao();d.setEvento(e);d.setData(data);d.setDescricao(descricao==null||descricao.isBlank()?"Programação diária":descricao.trim());d.setObservacoes(observacoes);if(salaId!=null)d.setSalaCirurgica(salas.findById(salaId).orElse(null));dias.save(d);r.addFlashAttribute("sucesso","Dia incluído na programação.");return "redirect:/mutiroes/"+id+"/dias";}
 @PostMapping("/dias/{diaId}/equipe") public String adicionarEquipe(@PathVariable Long diaId,@RequestParam Long colaboradorId,@RequestParam String funcaoNoMutirao,@RequestParam(required=false) Long salaId,RedirectAttributes r){DiaMutirao d=dias.findById(diaId).orElse(null);if(d==null){r.addFlashAttribute("erro","Dia de mutirão não encontrado.");return "redirect:/mutiroes";}Colaborador c=colaboradores.findById(colaboradorId).orElse(null);String func=funcaoNoMutirao==null?"":funcaoNoMutirao.trim();if(c==null||!c.isAtivo()||func.isBlank()||func.length()>100){r.addFlashAttribute("erro","Selecione um colaborador ativo e informe a função no mutirão.");return "redirect:/mutiroes/"+d.getEvento().getId()+"/dias";}if(equipes.existsByDiaIdAndColaboradorIdAndFuncaoNoMutiraoIgnoreCase(diaId,colaboradorId,func)){r.addFlashAttribute("erro","Este colaborador já está atribuído a essa função neste dia.");return "redirect:/mutiroes/"+d.getEvento().getId()+"/dias";}if(escalaPlantaoRepository.existsByColaboradorIdAndDataPlantao(colaboradorId,d.getData())){r.addFlashAttribute("erro","Este colaborador já possui plantão cadastrado nesta data. Revise a escala antes de escalá-lo no mutirão.");return "redirect:/mutiroes/"+d.getEvento().getId()+"/dias";}EquipeDiaMutirao item=new EquipeDiaMutirao();item.setDia(d);item.setColaborador(c);item.setFuncaoNoMutirao(func);if(salaId!=null)item.setSalaCirurgica(salas.findById(salaId).orElse(null));equipes.save(item);r.addFlashAttribute("sucesso","Colaborador escalado para este dia.");return "redirect:/mutiroes/"+d.getEvento().getId()+"/dias";}
 @PostMapping("/equipe/{id}/remover") public String removerEquipe(@PathVariable Long id,RedirectAttributes r){EquipeDiaMutirao item=equipes.findById(id).orElse(null);if(item==null){r.addFlashAttribute("erro","Atribuição não encontrada.");return "redirect:/mutiroes";}Long eventoId=item.getDia().getEvento().getId();equipes.delete(item);r.addFlashAttribute("sucesso","Atribuição removida.");return "redirect:/mutiroes/"+eventoId+"/dias";}
}
